CREATE VIEW public.camera_listings_view AS
 SELECT l.listing_id,
    l.title,
    l.description,
    l.price_eur,
    l.seller_location,
    l.date_posted,
    l.is_active,
    l.camera_confidence_score,
    l.camera_match_method,
    c.brand,
    c.model,
    c.model_original,
    c.mount,
    c.sensor,
    c.camera_type,
    c.category,
    c.release_year,
    c.resolution,
    c.has_4k,
    c.has_8k
   FROM (public.listings l
     LEFT JOIN public.camera_reference c ON ((l.matched_camera_id = c.id)))
  WHERE ((l.category)::text = 'camera'::text);


