--
-- Name: cpu_complete_data; Type: VIEW; Schema: public; Owner: crawler
--

CREATE VIEW public.cpu_complete_data AS
 SELECT cr.id AS cpu_reference_id,
    cr.producer,
    cr.cpu_name,
    cr.processor_number,
    cr.cores,
    cr.threads,
    cr.base_freq,
    cr.socket,
    cr.tdp_w,
    r23.cinebench_r23_single,
    r23.cinebench_r23_multi,
    r26.cinebench_r26_single,
    r26.cinebench_r26_multi,
    pm.passmark_score,
    pp.price_eur AS pcpartpicker_price,
    pp.rating AS pcpartpicker_rating,
        CASE
            WHEN (r23.id IS NOT NULL) THEN true
            ELSE false
        END AS has_r23,
        CASE
            WHEN (r26.id IS NOT NULL) THEN true
            ELSE false
        END AS has_r26,
        CASE
            WHEN (pm.id IS NOT NULL) THEN true
            ELSE false
        END AS has_passmark,
        CASE
            WHEN (pp.id IS NOT NULL) THEN true
            ELSE false
        END AS has_pcpartpicker,
    (((
        CASE
            WHEN (r23.id IS NOT NULL) THEN 1
            ELSE 0
        END +
        CASE
            WHEN (r26.id IS NOT NULL) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (pm.id IS NOT NULL) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (pp.id IS NOT NULL) THEN 1
            ELSE 0
        END) AS data_completeness_score
   FROM (((((public.cpu_reference cr
     LEFT JOIN public.cpu_name_matches cnm ON ((cr.id = cnm.cpu_reference_id)))
     LEFT JOIN public.cpu_benchmarks_r23 r23 ON (((cnm.r23_cpu_name)::text = (r23.cpu_name)::text)))
     LEFT JOIN public.cpu_benchmarks_r26 r26 ON (((cnm.r26_cpu_name)::text = (r26.cpu_name)::text)))
     LEFT JOIN public.cpu_benchmarks_passmark pm ON (((cnm.passmark_cpu_name)::text = (pm.cpu_name)::text)))
     LEFT JOIN public.cpu_prices_pcpartpicker pp ON (((cnm.pcpartpicker_name)::text = (pp.name)::text)));


ALTER TABLE public.cpu_complete_data OWNER TO crawler;

--
-- Name: cpu_match_summary; Type: VIEW; Schema: public; Owner: crawler
--

CREATE VIEW public.cpu_match_summary AS
 SELECT 'Cinebench R23'::text AS source,
    count(DISTINCT cnm.cpu_reference_id) AS matched_count,
    ( SELECT count(*) AS count
           FROM public.cpu_reference) AS total_cpus,
    round((((count(DISTINCT cnm.cpu_reference_id))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.cpu_reference), 0))::numeric), 2) AS match_percentage
   FROM public.cpu_name_matches cnm
  WHERE (cnm.r23_cpu_name IS NOT NULL)
UNION ALL
 SELECT 'Cinebench 2026'::text AS source,
    count(DISTINCT cnm.cpu_reference_id) AS matched_count,
    ( SELECT count(*) AS count
           FROM public.cpu_reference) AS total_cpus,
    round((((count(DISTINCT cnm.cpu_reference_id))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.cpu_reference), 0))::numeric), 2) AS match_percentage
   FROM public.cpu_name_matches cnm
  WHERE (cnm.r26_cpu_name IS NOT NULL)
UNION ALL
 SELECT 'PassMark'::text AS source,
    count(DISTINCT cnm.cpu_reference_id) AS matched_count,
    ( SELECT count(*) AS count
           FROM public.cpu_reference) AS total_cpus,
    round((((count(DISTINCT cnm.cpu_reference_id))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.cpu_reference), 0))::numeric), 2) AS match_percentage
   FROM public.cpu_name_matches cnm
  WHERE (cnm.passmark_cpu_name IS NOT NULL)
UNION ALL
 SELECT 'PCPartPicker'::text AS source,
    count(DISTINCT cnm.cpu_reference_id) AS matched_count,
    ( SELECT count(*) AS count
           FROM public.cpu_reference) AS total_cpus,
    round((((count(DISTINCT cnm.cpu_reference_id))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.cpu_reference), 0))::numeric), 2) AS match_percentage
   FROM public.cpu_name_matches cnm
  WHERE (cnm.pcpartpicker_name IS NOT NULL)
UNION ALL
 SELECT 'Any Source'::text AS source,
    count(DISTINCT cpu_name_matches.cpu_reference_id) AS matched_count,
    ( SELECT count(*) AS count
           FROM public.cpu_reference) AS total_cpus,
    round((((count(DISTINCT cpu_name_matches.cpu_reference_id))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.cpu_reference), 0))::numeric), 2) AS match_percentage
   FROM public.cpu_name_matches;


ALTER TABLE public.cpu_match_summary OWNER TO crawler;

