--
-- Name: cpu_unmatched_analysis; Type: VIEW; Schema: public; Owner: crawler
--

CREATE VIEW public.cpu_unmatched_analysis AS
 SELECT cr.id,
    cr.producer,
    cr.cpu_name,
    cr.processor_number,
    cr.cores,
    cr.threads,
    cr.socket,
        CASE
            WHEN (cnm.cpu_reference_id IS NULL) THEN 'No matches found'::text
            ELSE 'Partial match'::text
        END AS match_status
   FROM (public.cpu_reference cr
     LEFT JOIN public.cpu_name_matches cnm ON ((cr.id = cnm.cpu_reference_id)))
  WHERE ((cnm.cpu_reference_id IS NULL) OR ((cnm.r23_cpu_name IS NULL) AND (cnm.r26_cpu_name IS NULL) AND (cnm.passmark_cpu_name IS NULL) AND (cnm.pcpartpicker_name IS NULL)));


